(6476596, 962895, 12611, '<td valign="top">I love the lines of the wings and how they skirt dangerously close to the sides of the frame; so whisper thin at the ends, great bird pose, great shot.</td>', 'I love the lines of the wings and how they skirt dangerously close to the sides of the frame; so whisper thin at the ends, great bird pose, great shot.', '2011-07-20 10:10:03.000000', NULL, 1),
(6476598, 963086, 12611, '<td valign="top">A perfect shot- wiggly lines of shadow and land dance with waves against a sky, rippled with lavender and Payne''s gray. The figure is superb as well. theres hope in this shot, perhaps it deserves a more esoteric title- such as "surfer of light" excellent work.</td>', 'A perfect shot- wiggly lines of shadow and land dance with waves against a sky, rippled with lavender and Payne''s gray. The figure is superb as well. theres hope in this shot, perhaps it deserves a more esoteric title- such as "surfer of light" excellent work.', '2011-07-20 10:13:48.000000', NULL, 1),
(6476600, 963174, 12611, '<td valign="top">I love to look at this shot; the green is stunning, the sand is so rich and not faded white- great work- I hope the other voters let the colors and lines of this shot sink in a bit.</td>', 'I love to look at this shot; the green is stunning, the sand is so rich and not faded white- great work- I hope the other voters let the colors and lines of this shot sink in a bit.', '2011-07-20 10:15:05.000000', NULL, 1),
