INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6477297, 962876, 65234, '<td valign="top">OMG!!  It''s bad enough that there''s a Smurf movie coming out, but now they''re on DPC, too =:-O<br/> <br/>You probably could have found a bluer environment for them (a pool, perhaps?) but the Smurf-sized tree is pretty cute.  And they''re decidedly and famously blue ;-)</td>', 'OMG!!  It''s bad enough that there''s a Smurf movie coming out, but now they''re on DPC, too =:-O You probably could have found a bluer environment for them (a pool, perhaps?) but the Smurf-sized tree is pretty cute.  And they''re decidedly and famously blue ;-)', '2011-07-20 21:37:13.000000', NULL, 1),
(6477375, 962168, 133612, '<td valign="top">the weird perspective was interesting, but this seemed more like a snapshot with little reference to the rule of thirds to me.<br/></td>', 'the weird perspective was interesting, but this seemed more like a snapshot with little reference to the rule of thirds to me.', '2011-07-21 00:12:37.000000', NULL, 1),
(6477376, 962048, 133612, '<td valign="top">the colour of the berries seemed a little pixely to me, and to be honest the whole shot seemed a little washed out. sorry.</td>', 'the colour of the berries seemed a little pixely to me, and to be honest the whole shot seemed a little washed out. sorry.', '2011-07-21 00:14:10.000000', NULL, 1),
(6477378, 963202, 133612, '<td valign="top">nice work on not blowing out the sun/sky, but i felt the photo could have used a little something else?</td>', 'nice work on not blowing out the sun/sky, but i felt the photo could have used a little something else?', '2011-07-21 00:15:43.000000', NULL, 1),
(6477379, 962445, 133612, '<td valign="top">sorry but i didnt think that the green water fit the blue as primary colour brief, so low score from me for this challenge, but a nice photo nonetheless<br/></td>', 'sorry but i didnt think that the green water fit the blue as primary colour brief, so low score from me for this challenge, but a nice photo nonetheless', '2011-07-21 00:16:49.000000', NULL, 1),
(6477380, 962876, 133612, '<td valign="top">not sure how this one fits the challenge, i would have expected a little more blue than just the smurfs. nice dof tho!</td>', 'not sure how this one fits the challenge, i would have expected a little more blue than just the smurfs. nice dof tho!', '2011-07-21 00:17:56.000000', NULL, 1),
(6477490, 962717, 97339, '<td valign="top">Great capture! I love the way the handle and tail point in the same direction. The concentration on the birds face is priceless!</td>', 'Great capture! I love the way the handle and tail point in the same direction. The concentration on the birds face is priceless!', '2011-07-21 04:23:32.000000', NULL, 1),
(6477605, 963080, 33736, '<td valign="top">Crystal clear! 7</td>', 'Crystal clear! 7', '2011-07-21 10:04:35.000000', NULL, 1),
(6477607, 962362, 33736, '<td valign="top">Love the delicate feel of this one.  Did you have something in background that give the image its blue cloud-like appearance?<br/><br/><i>Message edited by author 2011-07-27 04:42:51.</i></td>', 'Love the delicate feel of this one.  Did you have something in background that give the image its blue cloud-like appearance?', '2011-07-21 10:07:01.000000', '2011-07-27 05:42:51.000000', 1),
(6477612, 962852, 33736, '<td valign="top">Did you shoot this in the WB-Tungsten?   It''s a truly amazing shot.  7</td>', 'Did you shoot this in the WB-Tungsten?   It''s a truly amazing shot.  7', '2011-07-21 10:16:04.000000', NULL, 1),
(6477615, 962432, 117534, '<td valign="top">One of my very Favorites!</td>', 'One of my very Favorites!', '2011-07-21 10:32:12.000000', NULL, 1),
(6477631, 963199, 33736, '<td valign="top">No strong subject to look at (clouds just weren''t enough to pull my eyes.)</td>', 'No strong subject to look at (clouds just weren''t enough to pull my eyes.)', '2011-07-21 10:56:32.000000', NULL, 1),
(6477632, 963148, 33736, '<td valign="top">Your blues are definitely around the upper third area, but the ''star'' of this show seems to be "Pink &amp; Green - Centered".</td>', 'Your blues are definitely around the upper third area, but the ''star'' of this show seems to be "Pink & Green - Centered".', '2011-07-21 10:57:42.000000', NULL, 1),
(6477633, 963007, 33736, '<td valign="top">Too much over-exposed and under-exposed, and a lot of ''stuff'' in the overall image.</td>', 'Too much over-exposed and under-exposed, and a lot of ''stuff'' in the overall image.', '2011-07-21 10:58:56.000000', NULL, 1),
(6477634, 962471, 33736, '<td valign="top">The eyes "have it"!</td>', 'The eyes "have it"!', '2011-07-21 10:59:42.000000', NULL, 1),
(6477635, 962804, 33736, '<td valign="top">It took me a while, but finally realized that the two out Vertical Thirds are solid blue.  Then you have some blue thing in each of the the Horizontal Thirds.  You sure covered the bases!  lollllll</td>', 'It took me a while, but finally realized that the two out Vertical Thirds are solid blue.  Then you have some blue thing in each of the the Horizontal Thirds.  You sure covered the bases!  lollllll', '2011-07-21 11:01:42.000000', NULL, 1),
(6477639, 962617, 33736, '<td valign="top">Terrific image.  The Thirds part is giving me some pause (it''s so strong in the halves or the whole.)</td>', 'Terrific image.  The Thirds part is giving me some pause (it''s so strong in the halves or the whole.)', '2011-07-21 11:04:44.000000', NULL, 1),
(6477640, 962865, 33736, '<td valign="top">So overexposed.  If this had been shot on an overcast day with just the green leaves and the blue guitar, it might have worked.</td>', 'So overexposed.  If this had been shot on an overcast day with just the green leaves and the blue guitar, it might have worked.', '2011-07-21 11:06:18.000000', NULL, 1),
